23	// Submit queues a render and waits for it.
24	func (q *Queue) Submit(ctx context.Context, doc *Doc) ([]byte, error) {
25		j := job{ctx: ctx, doc: doc, done: make(chan result, 1)}
26		q.jobs <- j
27		r := <-j.done
28		return r.pdf, r.err
29	}

