// Package metrics holds quill-server's Prometheus metrics.
package metrics

import "github.com/prometheus/client_golang/prometheus"

var (
	Renders = prometheus.NewCounterVec(prometheus.CounterOpts{
		Name: "quill_renders_total",
		Help: "Renders finished, by theme and result (ok or error).",
	}, []string{"theme", "result"})

	RenderSeconds = prometheus.NewHistogramVec(prometheus.HistogramOpts{
		Name: "quill_render_seconds",
		Help: "Time to render a document, in seconds.",
	}, []string{"theme"})

	QueueDepth = prometheus.NewGauge(prometheus.GaugeOpts{
		Name: "quill_render_queue_depth",
		Help: "Renders waiting for a worker.",
	})
)

func init() {
	prometheus.MustRegister(Renders, RenderSeconds, QueueDepth)
}

