func TestQueueCountsRenders(t *testing.T) {
	q := NewQueue(1)
	defer q.Close()
	before := testutil.ToFloat64(metrics.Renders.WithLabelValues("paper", "ok"))
	if _, err := q.Submit(context.Background(), testDoc("paper")); err != nil {
		t.Fatal(err)
	}
	if got := testutil.ToFloat64(metrics.Renders.WithLabelValues("paper", "ok")) - before; got != 1 {
		t.Errorf("renders counted = %v, want 1", got)
	}
	if got := testutil.ToFloat64(metrics.QueueDepth); got != 0 {
		t.Errorf("queue depth after the render = %v, want 0", got)
	}
}

