package metrics

import (
	"testing"

	"github.com/prometheus/client_golang/prometheus"
	dto "github.com/prometheus/client_model/go"
)

func TestRenderBucketsReachTwoMinutes(t *testing.T) {
	RenderSeconds.WithLabelValues("test").Observe(90)
	mfs, err := prometheus.DefaultGatherer.Gather()
	if err != nil {
		t.Fatal(err)
	}
	for _, mf := range mfs {
		if mf.GetName() != "quill_render_seconds" {
			continue
		}
		var h *dto.Histogram = mf.GetMetric()[0].GetHistogram()
		b := h.GetBucket()
		if top := b[len(b)-1].GetUpperBound(); top < 120 {
			t.Fatalf("highest bucket %vs, want at least 120s", top)
		}
		return
	}
	t.Fatal("quill_render_seconds not gathered")
}
